#!/usr/bin/env python3
"""Regenerates src/core/cairn_js.cpp from src/web/cairn.js (the unit tests fail if they drift apart).
Run from the repository root:  python3 tools/gen_js.py"""
src = open('src/web/cairn.js', encoding='utf-8').read()
assert ')CAIRNJS"' not in src
open('src/core/cairn_js.cpp', 'w', encoding='utf-8', newline='\n').write(
    '// GENERATED by tools/gen_js.py from src/web/cairn.js. Do not edit by hand.\n'
    '#include "export.h"\n\nnamespace cairn {\n\n'
    'const char* cairnJsSource() {\n  return R"CAIRNJS(' + src + ')CAIRNJS";\n}\n\n}  // namespace cairn\n')
